function Notice({ notice, close }: { notice: Notice; close: () => void }) {
  if (!notice) return null;
  const tone = notice.kind === 'success' ? 'border-emerald-200 bg-emerald-50 text-emerald-800' : notice.kind === 'warning' ? 'border-amber-200 bg-amber-50 text-amber-800' : 'border-sky-200 bg-sky-50 text-sky-800';
  return <div className={`fixed bottom-6 left-6 z-50 flex max-w-sm items-center gap-3 rounded-xl border px-4 py-3 text-sm font-semibold shadow-xl ${tone}`} role="status" data-testid="status-notice"><CheckCircle2 className="size-5 shrink-0" /><span>{notice.text}</span><button type="button" onClick={close} aria-label="إغلاق" data-testid="button-close-notice"><X className="size-4" /></button></div>;
}

